import { timestamp, uuid } from "drizzle-orm/pg-core";

/** Every table carries tenant_id (CLAUDE.md §2). */
export const tenantIdColumn = () => uuid("tenant_id").notNull();

/** Row identifier, generated by the database. */
export const idColumn = () => uuid("id").notNull().defaultRandom();

/**
 * When this row was written to the database. This is a measured fact about our
 * own system, never a stand-in for when something happened in the world.
 */
export const createdAtColumn = () =>
  timestamp("created_at", { withTimezone: true }).notNull().defaultNow();

/** A nullable point in time. Null means "not known"; there is never a default. */
export const optionalTimestamp = (name: string) => timestamp(name, { withTimezone: true });
